INSERT INTO contents (content_id, program_id, title, body, content_type, status) VALUES (105, 103, 'Chính Sách & Điều Kiện Sử Dụng: Membership Lai Towa - 1 Khách - 7 Ưu Đãi - Tầng 28 Sedona Suites', $BODY$Điều kiện sử dụng

- Thời hạn sử dụng voucher: từ 31/07/2026 đến 31/07/2027.

- Địa điểm sử dụng voucher: Lai - Towa - Tầng 28 Sedona Suites (Bên cạnh Sài Gòn Center) 92-94 Nam Kỳ Khởi Nghĩa, Phường Sài Gòn, TP. Hồ Chí Minh - Hotline: 0903 116 038.

- Khách hàng cung cấp thông tin (tên và số điện thoại) để kích hoạt thẻ tại thời điểm mua voucher qua số hotline: 0903 116 038. Thẻ chỉ được kích hoạt ngày kế tiếp sau khi mua thành công.

- Khách hàng vui lòng liên hệ đặt chỗ trước 24 giờ khi đến theo. Việc đặt bàn phụ thuộc vào tình trạng chỗ trống và khả năng phục vụ của nhà hàng.

- Voucher áp dụng cho Membership Lai Towa chỉ với 1.111.000 VNĐ (Giá gốc 2.500.000 VNĐ) - Ưu đãi cực sốc  - Ngắm trọn view Sài Gòn về đêm từ tầng 28.

Nội dung ưu đãi Membership bao gồm 7 ưu đãi sau:

- 01 con vịt quay Bắc Kinh 2 món cho 4  người

- 01 set menu món Nhật cho 2 khách

- 02 suất ăn trưa (món Hoa từ thứ 2 - thứ 6, món Nhật từ thứ 2 - Chủ nhật) dành cho 2 người

- 01 ly signature cocktail hoặc mocktail

- 01 Gift voucher 500.000 đồng (áp dụng cho menu alacarte)

- Giảm 15% tối đa 2.000.000 VNĐ trên tất cả hóa đơn sử dụng dịch vụ A La Carte, trước thuế và các phí dịch vụ.

- Mỗi thẻ chỉ được sử dụng 01 ưu đãi/ lần đặt bàn và một hóa đơn. KHÔNG hỗ trợ tách bill, ghép bàn.

- Thời gian phục vụ: Mỗi ngày 11h30-22h00 l Last order 21h45

- Sử dụng 01 voucher/ 01 thẻ thành viên/ 01 bàn.  Giá đã bao gồm VAT và phí phụ vụ.

- Khách hàng phải xuất trình mã voucher hợp lệ trước khi sử dụng dịch vụ.

- Voucher không được quy đổi thành tiền mặt, không hoàn lại tiền thừa và không dùng để mua voucher hoặc thẻ.

- Khi khách hàng mua thẻ trên Hotdeal sẽ kích hoạt luôn thẻ, lần gần nhất khi Khách hàng sử dụng ưu đãi khi đến nhà hàng nhân viên sẽ đưa thẻ vật lý cho khách.

- Không áp dụng các ngày Lễ, Tết, các ngày lễ đặc biệt khác (14/02, 08/03, 20/10, 24/12,...) và các ngày có sự kiện đăc biệt tại Nhà hàng.

- Nhà hàng có quyền kiểm soát điều khoản và điều kiện.

- Thẻ có hiệu lực 12 tháng kể từ ngày kích hoạt.

- Chỉ áp dụng tại nhà hàng, không áp dụng mua mang đi.

- Có thể linh động theo báo cáo hàng hóa mỗi ngày tại Outlet.

- Sản phẩm tặng không có giá trị quy đổi tiền mặt.

Không áp dụng đồng thời với các chương trình và Menu đặc biệt khác tại nhà hàng (Dimsum đồng giá, Menu ăn trưa, Set menu đặc biệt,...).

- Chỉ áp dụng ưu đãi khi khách hàng xuất trình thẻ vật lý tại nhà hàng.

- Khách hàng vui lòng thông báo trước về dị ứng thực phẩm hoặc yêu cầu ăn uống đặc biệt. Nhà hàng sẽ hỗ trợ trong phạm vi có thể.

- Thanh toán online nhận ngay voucher điện tử.$BODY$, 'POLICY', 'ACTIVE');
INSERT INTO contents (content_id, program_id, title, body, content_type, status) VALUES (106, 103, 'Trải Nghiệm Dịch Vụ & Điểm Nổi Bật: Membership Lai Towa - 1 Khách - 7 Ưu Đãi - Tầng 28 Sedona Suites', $BODY$Thông tin chi tiết

Nếu bạn yêu thích những trải nghiệm ẩm thực cao cấp, thường xuyên gặp gỡ đối tác, hẹn hò hay đơn giản là muốn tận hưởng những bữa ăn chất lượng trong không gian sang trọng, thì Membership Lai - Towa chính là ưu đãi không thể bỏ lỡ. Với mức giá chỉ 1.111.000 VNĐ (giá gốc 2.500.000 VNĐ), chiếc thẻ membership này mang đến nhiều đặc quyền hấp dẫn, giúp bạn thưởng thức những món ăn đặc sắc của hai nhà hàng nổi tiếng Lai và Towa, đồng thời tiết kiệm đáng kể chi phí cho những lần dùng bữa tiếp theo.

Quyền lợi khi sở hữu Membership Lai - Towa:

- 01 con vịt quay Bắc Kinh 2 món cho 4  người

- 01 set menu món Nhật cho 2 khách

- 02 suất ăn trưa (món Hoa từ thứ 2 - thứ 6, món Nhật từ thứ 2 - Chủ nhật) dành cho 2 người

- 01 ly signature cocktail hoặc mocktail

- 01 Gift voucher 500.000 đồng (áp dụng cho menu alacarte)

- Giảm 15% tối đa 2.000.000 VNĐ trên tất cả hóa đơn sử dụng dịch vụ A La Carte, trước thuế và các phí dịch vụ.

LAI - TOWA - ĐIỂM HẸN CỦA TINH HOA ẨM THỰC HOA & NHẬT

Tọa lạc tại tầng 28 Sedona Suites, ngay cạnh Saigon Centre, Lai - Towa là điểm đến được nhiều thực khách yêu thích nhờ sự kết hợp độc đáo giữa hai nền ẩm thực đặc sắc trong cùng một không gian đẳng cấp.

Lai - Cantonese Restaurant - Nét tinh túy của ẩm thực Quảng Đông

Lai chinh phục thực khách bằng những món Hoa cao cấp được chế biến công phu, nổi bật với Vịt quay Bắc Kinh, dimsum thủ công và nhiều món hải sản thượng hạng. Mỗi món ăn đều được chăm chút từ nguyên liệu đến hương vị, mang đến trải nghiệm chuẩn vị trong không gian sang trọng, ấm cúng.

Towa Japanese Cuisine & Louge - Trọn vẹn hương vị Nhật Bản

Towa mang đến những món ăn Nhật tinh tế với sushi, sashimi và các set menu được chế biến từ nguồn nguyên liệu tươi ngon. Không chỉ chú trọng hương vị, mỗi món ăn còn được trình bày đẹp mắt, thể hiện sự tỉ mỉ và tinh thần hiếu khách đặc trưng của Nhật Bản.

TRẢI NGHIỆM KHÔNG GIAN TRÊN CAO

Không chỉ gây ấn tượng bởi ẩm thực, Lai - Towa còn sở hữu vị trí đắc địa trên tầng 28 Sedona Suites, nơi bạn có thể chiêm ngưỡng toàn cảnh trung tâm TP. Hồ Chí Minh từ trên cao. Khi thành phố lên đèn, khung cảnh lung linh cùng không gian sang trọng sẽ biến mỗi bữa ăn trở thành một trải nghiệm đáng nhớ.

​

Chỉ 1.111.000 VNĐ để sở hữu Membership Lai - Towa trị giá 2.500.000 VNĐ cùng hàng loạt quyền lợi hấp dẫn. Số lượng có hạn, nhanh tay đăng ký để tận hưởng những đặc quyền ẩm thực đẳng cấp ngay hôm nay!$BODY$, 'ARTICLE', 'ACTIVE');


