INSERT INTO contents (content_id, program_id, title, body, content_type, status) VALUES (113, 107, 'Chính Sách & Điều Kiện Sử Dụng: Cỏ Nội - Buffet Chay Trưa/ Tối Tháng 7 Âm Lịch Hơn 40 Món', $BODY$Điều kiện sử dụng

- Thời hạn sử dụng voucher: 10/09/2026.

- Địa điểm sử dụng voucher: Nhà hàng Cỏ Nội - Lầu 7 - Khách sạn Bông Sen - 117-123 Đồng Khởi, Phường Sài Gòn, Tp. HCM. ĐT: 028 3829 1623 - Hotline: 0902184195.

- Áp dụng cho Buffet chay buổi trưa/ tối tháng 7 âm lịch Nhà hàng Cỏ Nội - Khách sạn Bông Sen. Tham khảo menu tại đây.

1. Buffet chay buổi trưa/ tối hàng ngày tháng 7 âm lịch ưu đãi giảm chỉ còn 209,000đ (giá gốc 239,000đ), trừ các ngày 14, 15 tháng 7 âm lịch.

2. Buffet chay buổi trưa/ tối các ngày 14, 15 tháng 7 âm lịch ưu đãi giảm chỉ còn 229,000đ (giá gốc 259,000đ).

- Thời gian áp dụng: từ 11h - 14h & 18h - 21h, tất cả các ngày trong tuần (áp dụng lễ).

- Chính sách trẻ em:

+ Dưới 1,3m: 1/2 giá người lớn (thanh toán tại nhà hàng)

+ Từ 1,3m trở lên: Tính như giá người lớn

- Sử dụng 1 voucher/ 1 người/ 1 lần (không bù thêm tiền).

- Không giới hạn số voucher/ hóa đơn.

- Khách có thể mua nhiều voucher để sử dụng nhiều lần.

- Miễn phí nước uống bao gồm: trà đá, nước sâm, chè các loại. Nếu quý khách có nhu cầu sử dụng các loại nước uống khác, vui lòng order và thanh toán thêm tại nhà hàng.

- Phiếu đã bao gồm phí phục vụ và thuế VAT.

- Nhà hàng chịu trách nhiệm xuất hóa đơn tài chính theo giá bán voucher và giá trị sử dụng thực tế khi khách hàng yêu cầu.

- Vui lòng không lãng phí và để thừa, nhà hàng thu phí lãng phí ở mức 20% trong trường hợp để thừa nhiều đồ ăn.

- Khách hàng vui lòng liên hệ 028 3829 1623 - Hotline: 0948205090 - 0902184195 đặt chỗ trước khi đến để được phục vụ tốt nhất. (Trong trường hợp khách hàng không đặt chỗ trước, nhà hàng sẽ không chịu trách nhiệm nếu có bất kỳ sai sót nào).

- Không áp dụng đồng thời với các chương trình khuyến mãi khác.

- Phiếu không có giá trị quy đổi thành tiền mặt, không trả lại tiền thừa.

- Thanh toán online nhận ngay voucher điện tử.$BODY$, 'POLICY', 'ACTIVE');
INSERT INTO contents (content_id, program_id, title, body, content_type, status) VALUES (114, 107, 'Trải Nghiệm Dịch Vụ & Điểm Nổi Bật: Cỏ Nội - Buffet Chay Trưa/ Tối Tháng 7 Âm Lịch Hơn 40 Món', $BODY$Thông tin chi tiết

Hòa cùng không khí mùa Vu Lan, Nhà hàng Cỏ Nội - Khách sạn Bông Sen giới thiệu chương trình Buffet chay buổi trưa và buổi tối trong tháng 7 âm lịch, mang đến hành trình khám phá ẩm thực chay với nhiều món ăn hấp dẫn được chế biến công phu từ nguyên liệu tươi ngon. Không chỉ là một bữa ăn, đây còn là cơ hội để bạn và gia đình tận hưởng những phút giây sum vầy, an yên trong không gian sang trọng, ấm cúng và đậm chất truyền thống.

Với mong muốn mang lại cho thực khách những phong cách ẩm thực chay của nhiều nơi khác nhau, các món chính trong buffet chay của Nhà hàng Cỏ Nội đảm bảo mang lại cho bạn sự hài lòng với những món chay phong phú như: Cà ri kiểu Ấn, mì xào Phúc Kiến, bắp cải Bát Nhã, há cảo hấp Lani, giả gà Niệm Tâm và xôi chiên phồng. Món xào: rau và nấm tự chọn, mướp đắng nhồi sakê...

​

​

Buffet chay Cỏ Nội còn có những món ăn cơm hấp dẫn gồm: Cơm chiên cà ri Thái, cơm chiên sen Lục Niệm, bún riêu Định Huệ, cơm trắng ăn với: Măng kho tộ, nấm kho tiêu, mì căn xào sả ớt, đậu hủ chiên sả ớt. Ngoài ra, nếu thích ăn lẩu, bạn còn có thể thưởng thức món lẩu nấm chua cay ăn với bún tươi.

Sau khi đã ăn xong những món chính, các bạn sẽ được thưởng thức các món tráng miệng thơm ngon bao gồm các loại bánh, chè, rau câu và trái cây.

Nhà hàng Cỏ Nội không chỉ hấp dẫn thực khách bởi thực đơn món ăn phong phú, hấp dẫn mà còn bởi phong cách phục vụ chuyên nghiệp, chu đáo. Không gian sang trọng, thuần Việt với sức chứa 100 khách, gồm 01 phòng riêng và có ban công sân vườn tầng 7, view ngắm nhìn con đường Đồng Khởi, Đông Du từ trên cao.

Click MUA ngay bạn nhé!$BODY$, 'ARTICLE', 'ACTIVE');


