INSERT INTO contents (content_id, program_id, title, body, content_type, status) VALUES (115, 108, 'Chính Sách & Điều Kiện Sử Dụng: DGemma Thủ Đức - Buffet Chay Cao Cấp Trưa/ Tối', $BODY$Điều kiện sử dụng

