INSERT INTO contents (content_id, program_id, title, body, content_type, status) VALUES (129, 115, 'Chính Sách & Điều Kiện Sử Dụng: Buffet Gánh Bông Sen - Ẩm Thực 3 Miền - Tối Cả Tuần', $BODY$Điều kiện sử dụng

- Thời hạn sử dụng voucher: từ 22/07/2026 đến 22/10/2026.

- Địa điểm sử dụng voucher: Buffet Gánh Bông Sen - Khách sạn Bông Sen - Tầng 1, 117 - 123 Đồng Khởi, Phường Sài Gòn, Tp. HCM. ĐT: (028) 3829 6239. Hotline: 0901 141 497.

