INSERT INTO contents (content_id, program_id, title, body, content_type, status) VALUES (133, 117, 'Chính Sách & Điều Kiện Sử Dụng: Yuhua Hoàng Hoa Thám - Buffet Lẩu Đài Loan Hơn 80 Món Nhúng', $BODY$Điều kiện sử dụng

