INSERT INTO contents (content_id, program_id, title, body, content_type, status) VALUES (137, 119, 'Chính Sách & Điều Kiện Sử Dụng: Hầm Rượu Aum Wincellar - Set Menu Craft Beer/ Rượu Vang Cho 2 Người', $BODY$Điều kiện sử dụng

