INSERT INTO contents (content_id, program_id, title, body, content_type, status) VALUES (153, 127, 'Chính Sách & Điều Kiện Sử Dụng: Membership Lai Towa - 1 Khách - 7 Ưu Đãi - Tầng 28 Sedona Suites', $BODY$Điều kiện sử dụng

- Thời hạn sử dụng voucher: từ 31/07/2026 đến 31/07/2027.

- Địa điểm sử dụng voucher: Lai - Towa - Tầng 28 Sedona Suites (Bên cạnh Sài Gòn Center) 92-94 Nam Kỳ Khởi Nghĩa, Phường Sài Gòn, TP. Hồ Chí Minh - Hotline: 0903 116 038.

