INSERT INTO contents (content_id, program_id, title, body, content_type, status) VALUES (161, 131, 'Chính Sách & Điều Kiện Sử Dụng: ROS - Yacht Club - Set Menu Ăn Trưa Tại Nhà Hàng Bên Sông Sài Gòn', $BODY$Điều kiện sử dụng

