INSERT INTO contents (content_id, program_id, title, body, content_type, status) VALUES (171, 136, 'Chính Sách & Điều Kiện Sử Dụng: Northern Charm Hotel - Combo Ẩm Thực & Vé Bơi Cho 1-2 Khách', $BODY$Điều kiện sử dụng

- Thời hạn sử dụng voucher: từ 10/03/2026 đến 10/03/2027.

- Địa điểm sử dụng voucher: Hồ Bơi - Tầng 17, Northern Charm Hotel - 12 Lý Tự Trọng, Phường Sài Gòn, Tp.HCM. Hotline: 0902 286 689 hoặc 028 3822 5252.

- Voucher áp dụng cho: Trọn gói ăn uống và sử dụng hồ bơi, gồm:

+ Chọn 01 trong 03 set menu dành cho 01 - 02 người.

+ 01 hoặc 02 vé bơi (tùy set menu).

+ Miễn phí sử dụng khăn tắm.

- Tham khảo menu tại đây.

1/ Set menu 1 + 01 Đồ uống + 01 Vé bơi: ưu đãi giảm chỉ còn 495,000đ (giá gốc 550,000đ).

2/ Set menu 2 + 02 Đồ uống + 02 Vé bơi: ưu đãi giảm chỉ còn 855,000đ (giá gốc 950,000đ).

3/ Set menu 3 + 02 Đồ uống + 02 Vé bơi: ưu đãi giảm chỉ còn 1,125,000đ (giá gốc 1,250,000đ).

- Thời gian áp dụng: từ 8h - 16h tất cả các ngày trong tuần. Không áp dụng các ngày lễ và các ngày đặc biệt khác của nhà hàng.

- Sử dụng 01 voucher/01 set + vé bơi (không bù tiền). Không giới hạn số lượng voucher/hóa đơn.

- Áp dụng tại chỗ. Không áp dụng cho mang về.

- Đã bao gồm VAT và phí phục vụ. Khách sạn có trách nhiệm xuất hóa đơn khi khách hàng yêu cầu. Thông tin hóa đơn phải được cung cấp trước 23:00 cùng ngày sử dụng dịch vụ. Sau thời gian này khách sạn sẽ không giải quyết.

- Khách hàng vui lòng xuất trình voucher trước khi sử dụng dịch vụ.

- Một khách hàng có thể mua nhiều phiếu.

- Khách hàng vui lòng đặt chỗ trước khi đến. Trường hợp không đặt chỗ trước, nhà hàng xin phép được cáo lỗi nếu không còn chỗ trống.

- Không áp dụng đồng thời với các chương trình khuyến mãi, giảm giá hoặc voucher khác.

- Không có giá trị quy đổi thành tiền, không hoàn trả tiền thừa.

- Thanh toán online nhận ngay voucher điện tử.$BODY$, 'POLICY', 'ACTIVE');
INSERT INTO contents (content_id, program_id, title, body, content_type, status) VALUES (172, 136, 'Trải Nghiệm Dịch Vụ & Điểm Nổi Bật: Northern Charm Hotel - Combo Ẩm Thực & Vé Bơi Cho 1-2 Khách', $BODY$Thông tin chi tiết

Nếu bạn đang tìm kiếm một trải nghiệm kết hợp giữa ẩm thực hấp dẫn và không gian thư giãn lý tưởng giữa lòng thành phố, thì Set menu hảo hạng kèm vé bơi cho 01 - 02 khách tại hồ bơi tầng 17, Northern Charm Hotel chính là lựa chọn hoàn hảo dành cho bạn.

Tọa lạc trên tầng cao nhất của khách sạn, hồ bơi vô cực Northern Charm mang đến tầm nhìn toàn cảnh thành phố tuyệt đẹp. Không gian thoáng đãng, hiện đại và sang trọng, nơi bạn có thể thư giãn trong làn nước mát lành, thả mình giữa không trung và tận hưởng cảm giác an yên sau những giờ làm việc căng thẳng. Với voucher Hotdeal, bạn được trải nghiệm miễn phí sử dụng hồ bơi và khăn tắm 08:00 - 16:00.

Sau khi bơi lội, bạn sẽ được phục vụ những set menu hấp dẫn mang phong cách phương Tây hiện đại, được chế biến tỉ mỉ từ nguyên liệu tươi ngon.

