INSERT INTO contents (content_id, program_id, title, body, content_type, status) VALUES (183, 142, 'Chính Sách & Điều Kiện Sử Dụng: Skin Lab By Hung Nguyen - Trẻ Hóa Da Meso Không Kim Hàn Quốc', $BODY$Điều kiện sử dụng

