INSERT INTO contents (content_id, program_id, title, body, content_type, status) VALUES (199, 150, 'Chính Sách & Điều Kiện Sử Dụng: Grand Skin Care - Meso Không Kim Căng Bóng Da - Hiệu Quả 80%', $BODY$Điều kiện sử dụng

