INSERT INTO contents (content_id, program_id, title, body, content_type, status) VALUES (205, 153, 'Chính Sách & Điều Kiện Sử Dụng: Ty House Spa - Giảm Béo Siêu Tốc - Hiệu Quả Ngay Lần Đầu', $BODY$Điều kiện sử dụng

