INSERT INTO contents (content_id, program_id, title, body, content_type, status) VALUES (207, 154, 'Chính Sách & Điều Kiện Sử Dụng: Spa Thái Dương - Massage Body/ Foot/ Gội Đầu Dưỡng Sinh 90’', $BODY$Điều kiện sử dụng

