INSERT INTO contents (content_id, program_id, title, body, content_type, status) VALUES (219, 160, 'Chính Sách & Điều Kiện Sử Dụng: Ngọc Thanh Healthy - Trọn Gói Massage Body/ Foot 85’', $BODY$Điều kiện sử dụng

