INSERT INTO contents (content_id, program_id, title, body, content_type, status) VALUES (221, 161, 'Chính Sách & Điều Kiện Sử Dụng: VP OHUI - Trị Mụn/ Nám/ Thâm Mắt/ Hút Chì/ Trẻ Hóa/ Triệt Lông', $BODY$Điều kiện sử dụng

- Thời hạn sử dụng voucher: từ 26/06/2026 đến 26/09/2026.

- Địa điểm sử dụng voucher: Hệ Thống Văn Phòng Chăm Sóc Sắc Đẹp OHUI

+ 529/142 Huỳnh Văn Bánh, Phường 13, Quận Phú Nhuận. ĐT: 0963 641688 (Ms Duyên).

+ 463B/2 Cách Mạng Tháng Tám, Phường 13, Quận 10. ĐT: 0964 403775 (Ms Hương).

- Áp dụng cho 01 trong 06 gói dịch vụ làm đẹp cao cấp tại Hệ Thống Văn Phòng Chăm Sóc Sắc Đẹp OHUI.

+ Gói 1: Lấy sạch nhân mụn + Điều trị mụn + Trị thâm + Se khít chân lông + Đắp mặt nạ công nghệ cao của Hàn Quốc chuẩn y khoa, an toàn, không tái phát bằng tinh chất vàng 24k (90 phút).

+ Gói 2: Hút chì, thải độc tố + Đắp mặt nạ Purple De Mask - Hồi sinh cho làn da trắng mịn bằng tinh chất than hoạt tính (90 phút).

+ Gói 3: Điều trị nám mảng, nám chân sâu, nám do mụn thâm để lại, tàn nhang, trắng sáng da bằng tinh chất ngọc trai nhân sâm núi lên men (90 phút).

+ Gói 4: Cấy tinh chất vàng 24k nhân sâm núi hoàng kim trẻ hóa, căng bóng làn da 15 năm tuổi (90 phút).

+ Gói 5: Trị thâm quầng mắt, chống nhăn, nâng mí mắt, tiêu bọng mắt bằng tinh chất dung dịch nuôi dưỡng tế bào mầm và chất dẫn xuất Hesperidin (90 phút).

+ Gói 6: Trọn gói Triệt lông vĩnh viễn kết hợp trẻ hóa da, trị thâm vùng nách/ mép/ má/ trán công nghệ New Elight (IPL + RF) mới nhất 2026, siêu nhanh + không đau + an toàn + hiệu quả 100% (02 lần).

- Liệu trình được thực hiện chuyên nghiệp, đúng quy trình, đạt hiệu quả tối ưu.

- Cam kết sử dụng 100% mỹ phẩm cao cấp OHUI, The history of WHOO, SU:M37&ordm;.

- Thời gian áp dụng:

+ Quận Phú Nhuận: Áp dụng vào tất cả các ngày trong tuần (kể cả Lễ). Giờ áp dụng: 9h-18h.

+ Quận 3: Áp dụng vào tất cả các ngày trong tuần (kể cả Lễ). Giờ áp dụng: 8h30-19h30.

- Áp dụng cho cả nam và nữ.

- Một khách hàng được mua nhiều phiếu để tặng cho người thân, bạn bè...

- Sử dụng 01 phiếu/ 01 người/ 01 gói dịch vụ (Không bù tiền). Mỗi khách hàng sử dụng tối đa 02 phiếu.

- Không áp dụng đồng thời với các chương trình khuyến mãi khác.

- Khách hàng vui lòng đặt chỗ trước khi đến để được phục vụ tốt nhất.

- Phiếu không có giá trị quy đổi thành tiền mặt, không trả lại tiền thừa.

- Thanh toán online nhận ngay voucher điện tử.$BODY$, 'POLICY', 'ACTIVE');
INSERT INTO contents (content_id, program_id, title, body, content_type, status) VALUES (222, 161, 'Trải Nghiệm Dịch Vụ & Điểm Nổi Bật: VP OHUI - Trị Mụn/ Nám/ Thâm Mắt/ Hút Chì/ Trẻ Hóa/ Triệt Lông', $BODY$Thông tin chi tiết

Nhắc đến những thương hiệu mỹ phẩm nổi tiếng tại Hàn Quốc, không thể không nhắc đến OHUI. Đây là thương hiệu mỹ phẩm cao cấp được tin dùng số 1 ở Hàn Quốc. Có mặt tại Việt Nam từ năm 2005, đến nay, mỹ phẩm OHUI đã trở thành lựa chọn hàng đầu của nhiều chị em nhờ chất lượng vượt trội mà nó mang lại. Làm đẹp bằng mỹ phẩm OHUI là một trong những cách đơn giản mà hiệu quả để bạn có thể sở hữu làn da trắng sáng, mịn màng, căng bóng như sao Hàn. Voucher lần này của Hotdeal mang đến cho bạn cơ hội làm đẹp với các dòng sản phẩm của thương hiệu đình đám này bằng 01 trong 06 gói dịch vụ tại Hệ thống Văn phòng Chăm sóc Sắc đẹp OHUI: Điều trị mụn, thâm/ Hút chì/ Điều trị nám, tàn nhang/ Trẻ hóa da 15 năm tuổi/ Trị thâm mắt/ Triệt lông chỉ với 89.000 đồng.

Xuyên suốt các liệu trình, bạn sẽ được chăm sóc da bằng dòng mỹ phẩm OHUI của tập đoàn LG hàng đầu Hàn Quốc. Đây là một thương hiệu mỹ phẩm cao cấp được ưa chuộng bởi giới thượng lưu ở Hàn, được biết đến với các dòng sản phẩm được chế tạo từ các nguyên liệu thảo dược quý hiếm như nhân sâm hoang dã và hoa sen tuyết,... kết hợp giữa tinh hoa làm đẹp hoàng cung với y học phương Đông và công nghệ làm đẹp hiện đại nhất hiện nay. Những sản phẩm của OHUI không chỉ có thiết kế sang trọng, trang nhã, xứng tầm với người dùng cao cấp mà còn thực sự mang đến cho làn da bạn một vẻ đẹp hoàn hảo. Những sản phẩm của OHUI chú trọng giải quyết nhiều vấn đề về da, đặc biệt là ngăn ngừa lão hóa, trị mụn, xóa nám, tàn nhang bằng những tính năng vượt trội từ những nguyên liệu Đông y, giúp da khỏe lên từ bên trong, vô cùng an toàn cho làn da. Vì thế, mỹ phẩm OHUI đặc biệt thích hợp để sử dụng cho những liệu trình chăm sóc, điều trị da lần này.

​

Liệu trình chăm sóc, điều trị da tại Văn phòng Chăm sóc Sắc đẹp OHUI không chỉ sử dụng mỹ phẩm cao cấp OHUI, The history of WHOO, SU:M37&ordm; mà còn được thực hiện bởi các máy móc chuyên dụng và đội ngũ nhân viên giàu kinh nghiệm, đem đến hiệu quả làm đẹp tối ưu. Chỉ sau một lần trải nghiệm liệu trình, bạn sẽ cảm nhận sự thay đổi rõ rệt của làn da mình.

+ Gói 1: Lấy sạch nhân mụn + Điều trị mụn + Trị thâm + Se khít chân lông + Đắp mặt nạ công nghệ cao của Hàn Quốc chuẩn y khoa, an toàn, không tái phát bằng tinh chất vàng 24k (90 phút).

Lấy nhân mụn chuẩn Y khoa giúp loại bỏ 90% mụn trên bề mặt da: mụn ẩn, đầu đen, mụn do dị ứng, mụn mủ, mụn bọc, mụn lỗ chân lông... mà không sưng, không đau, không để lại vết thâm. Quy trình điều trị mụn với sự kết hợp của sản phẩm đặc trị mụn thương hiệu OHUI cao cấp kết hợp đèn đỏ sinh học, có tác dụng kháng viêm, diệt khuẩn, hỗ trợ trị mụn, se khít chân lông, đặc biệt làm giảm đáng kể tình trạng viêm của mụn trứng cá, giúp da sạch mụn, hồi phục độ sáng mịn và khỏe mạnh.

Liệu trình:

- Bước 1: Kiểm tra da phân tích tình trạng da.

- Bước 2: Ủ ánh sáng sinh học màu xanh lục giúp diệt khuẩn, làm kích nhân mụn ẩn dưới da trồi lên để dễ xử lý (dành cho da mụn nặng).

- Bước 3: Tẩy trang giúp loại bỏ lớp kem trang điểm, chống nắng, bụi bám trên bề mặt da.

- Bước 4: Rửa mặt bằng sữa rửa mặt đông y Hoàng Cung giúp loại bỏ sạch sâu bụi bẩn, bã nhờn trên da (sử dụng khăn giấy lụa làm sạch da mặt, mỗi khách một cặp, không dùng bọt biển, nên vệ sinh an toàn tuyệt đối).

- Bước 5: Tẩy tế bào chết bằng sản phẩm đông y chiết xuất từ 100% thảo dược đông y cao cấp, không gây trầy xước, không tổn thương da, nhẹ nhàng loại bỏ tế bào già chết, giúp các dưỡng chất hấp thụ sâu vào trong da.

- Bước 6: Xông nóng giải độc da bằng tinh dầu đặt trị mụn giúp giãn nở lỗ chân lông bít tắc, giúp nhẹ nhàng lấy nhân mụn mà không đau, không để lại sẹo.

- Bước 7: Hút mụn bằng ống thuỷ tinh chân không giúp hút sạch bã nhờn, bụi bẩn, vi khuẩn làm thông thoáng sâu trong lỗ chân lông (mỗi khách hàng một ống riêng biệt).

- Bước 8: Kiểm tra độ nhờn da qua ống thuỷ tinh chân không & ấn huyệt trên khuôn mặt giúp tuần hoàn máu, giúp cho quá trình trị liệu đạt hiệu quả cao.

- Bước 9: Sát khuẩn bằng thuốc tím Povidine và nước muối sinh lý.

- Bước 10: Sát khuẩn bộ dụng cụ bằng cồn.

- Bước 11: Tiến hành lấy nhân mụn, mụn ẩn, mụn đầu đen, mụn trứng cá, bằng dụng cụ chuyên khoa, an toàn, vệ sinh tuyệt đối (mỗi khách 1 bộ riêng biệt)- không để lại thâm sẹo.

- Bước 12: Sát trùng lại da lần nữa bằng Povidine làm sạch vi khuẩn.

- Bước 13: Đi tia điện tím giảm sưng kháng khuẩn, tiêu viêm cực mạnh, khử vi trùng, liền vùng da tổn thương do lấy mụn.

- Bước 14: Thoa serum đặc trị mụn lên bề mặt da.

- Bước 15: Dùng điện di ion đưa dưỡng chất thẩm thấu sâu vào da tăng hấp thụ collagen và elastin bị tổn thương do mụn kiềm dầu.

- Bước 16: Chiếu ánh sáng sinh học xanh lam chống nhiễm khuẩn giảm sưng giúp nhân mụn điều tiết tuyến nhờn.​

- Bước 17: Đắp mặt nạ lạnh thảo dược trị mụn tiêu diệt trọn ổ vi khuẩn mụn.

- Bước 18: Đắp mặt nạ điều trị mụn.

- Bước 19: Chiếu đèn ánh sáng sinh học điều trị mụn, lành vết thương, giảm sưng tấy (20 phút).

- Bước 20: Massage đầu vai cổ đả thông kinh mạch, giúp thư giãn, giảm đau đầu, nhức mỏi.

- Bước 21: Thoa thuốc đặc trị mụn.

- Bước 22: Đi búa lạnh đưa sóng siêu âm lạnh làm se khít mạch máu và lỗ chân lông làm mềm da, giảm đau, chống sưng tấy sau quá trình trị liệu.

- Bước 23: Thoa kem chống nắng bảo vệ da.

- Bước 24: Hướng dẫn cách chăm sóc da sau điều trị để tránh tái phát mụn và đạt hiệu quả tốt nhất.

- Kết thúc liệu trình 90&#39;.

- Cấy tinh chất vàng.

+ Gói 2: Hút chì, thải độc tố + Đắp mặt nạ Purple De Mask - Hồi sinh cho làn da trắng mịn bằng tinh chất than hoạt tính (90 phút).

Dịch vụ hút chì, thải độc tố giúp làn da loại bỏ những tạp chất tích tụ trong thời gian dài do môi trường ô nhiễm hoặc sử dụng mỹ phẩm. Từ đó, làn da được cải thiện tình trạng kích ứng, thâm sạm, sần sùi và hồi sinh trắng mịn rạng rỡ.

Liệu trình:

- Bước 1: Kiểm tra phân tích tình trạng da.

- Bước 2: Tẩy trang bằng sữa tẩy trang giúp làm sạch lớp trang điểm.

- Bước 3: Lau sạch bằng bông cotton khô lấy sạch kem tẩy trang.

- Bước 4: Rửa mặt bằng sữa rửa mặt giúp làm sạch sâu (sử dụng khăn giấy lụa làm sạch da mặt, mỗi khách một cặp, không dùng bọt biển, nên vệ sinh an toàn tuyệt đối) giúp làn da tươi sáng, mịn màng.

- Bước 5: Tẩy da chết giúp làm sạch tế bào chết và lớp biểu bì sần sùi thô ráp trên bề mặt da.

- Bước 6: Làm sạch lớp da chết đã bong.

- Bước 5: Xông hơi nóng giải độc da bằng tinh dầu xả chanh giúp giãn nở lỗ chân lông bít tắc.

- Bước 7: Hút mụn bằng ống thuỷ tinh chân không, giúp hút sạch bã nhờn, bụi bẩn, vi khuẩn mụn cám, mụn đầu đen làm thông thoáng sâu trong lỗ chân lông (mỗi khách hàng một ống riêng biệt).

- Bước 8: Kiểm tra độ nhờn da qua ống thuỷ tinh chân không & ấn huyệt trên khuôn mặt giúp tuần hoàn máu, giúp cho quá trình trị liệu đạt hiệu quả cao.

- Bước 9: Vệ sinh lại da.

- Bước 10: Massage giúp tuần hoàn máu, se lỗ chân lông giúp da săn chắc mịn màng. Kết hợp massage cổ, vai, gáy giúp giảm mệt mỏi, giảm đau nhức.

- Bước 11: Hút chì thải độc tố, bổ sung dưỡng chất sâu vào da.

- Bước 12: Đắp mặt nạ tinh tinh chất colagen vàng 24k và sâm giúp da trắng sáng mịn màng, tái tạo, dưỡng ẩm, đặc biệt chống lão hóa cho da.

- Bước 13: Chiếu ánh sáng sinh học giúp phục hồi da, tăng chỉ số sức khỏe cho làn da.

- Bước 14: Lau sạch mặt nạ.

- Bước 15: Thoa tinh chất trắng da, ngăn ngừa lão hóa, trắng sáng da.

- Bước 16: Chạy điện ion đưa tinh chất dưỡng trắng, ngăn ngừa lão hóa da.

- Bước 17: Chạy búa lạnh giúp se khít lỗ chân lông, khóa dưỡng chất lại trên da.

- Bước 18: Bôi kem dưỡng chống nắng.

- Bước 19: Hướng dẫn cách chăm sóc bảo vệ da.

+ Gói 3: Điều trị nám mảng, nám chân sâu, nám do mụn thâm để lại, tàn nhang, trắng sáng da bằng tinh chất ngọc trai nhân sâm núi lên men (90 phút).

Trong liệu trình này, Văn phòng Chăm sóc Sắc đẹp OHUI sẽ sử dụng tinh chất ngọc trai nhân sâm núi lên men để giúp da loại bỏ sắc tố melanin tối màu.

Tinh chất ngọc trai nhân sâm núi chứa nhiều dưỡng chất có lợi cho da với công dụng làm trắng, đánh bật những đốm đem và vết nám trên da hiệu quả. Trải nghiệm liệu trình với tinh chất ngọc trai nhân sâm núi còn làm da săn chắc, tăng liên kết chuỗi collagen và sản sinh collagen mới ngăn ngừa lão hóa, hạn chế hình thành vết nhăn, giúp da căng mịn tự nhiên và trắng sáng.

Liệu trình:

- Bước 1: Kiểm tra phân tích tình trạng da.

- Bước 2: Tẩy trang bằng sữa tẩy trang giúp làm sạch lớp trang điểm.

- Bước 3: Lau sạch bằng bông cotton khô lấy sạch kem tẩy trang.

- Bước 4: Rửa mặt bằng sữa rửa mặt giúp làm sạch sâu (sử dụng khăn giấy lụa làm sạch da mặt, mỗi khách một cặp, không dùng bọt biển, nên vệ sinh an toàn tuyệt đối) giúp làn da tươi sáng, mịn màng.

- Bước 5: Tẩy da chết giúp làm sạch tế bào chết và lớp biểu bì sần sùi thô ráp trên bề mặt da.

- Bước 6: Làm sạch lớp da chết đã bong.

- Bước 5: Xông hơi nóng giải độc da bằng tinh dầu xả chanh giúp giãn nở lỗ chân lông bít tắc.

- Bước 7: Hút mụn bằng ống thuỷ tinh chân không, giúp hút sạch bã nhờn, bụi bẩn, vi khuẩn mụn cám, mụn đầu đen làm thông thoáng sâu trong lỗ chân lông (mỗi khách hàng một ống riêng biệt).

- Bước 8: Kiểm tra độ nhờn da qua ống thuỷ tinh chân không & ấn huyệt trên khuôn mặt giúp tuần hoàn máu, giúp cho quá trình trị liệu đạt hiệu quả cao.

- Bước 9: Vệ sinh lại da.

- Bước 10: Massage giúp tuần hoàn máu, se lỗ chân lông giúp da săn chắc mịn màng. Kết hợp massage cổ, vai, gáy giúp giảm mệt mỏi, giảm đau nhức.

- Bước 11: Đi máy nano đưa tinh chất ngọc trai nhân sâm núi điều trị vấn đề da nám, giúp làm tan chân nám, đào thải và làm mờ vết thâm, nám, tàn nhang.

- Bước 12: Đắp mặt nạ tinh tinh chất colagen vàng 24k và sâm giúp da trắng sáng mịn màng, tái tạo, dưỡng ẩm, đặc biệt chống lão hóa cho da.

- Bước 13: Chiếu ánh sáng sinh học màu đỏ giúp phục hồi da, tăng chỉ số sức khỏe cho làn da, nuôi dưỡng colagen và Elastin mờ thâm nám.

- Bước 14: Lau sạch mặt nạ.

- Bước 15: Thoa tinh chất trắng da, ngăn ngừa lão hóa, trắng sáng da.

- Bước 16: Chạy điện ion đưa tinh chất dưỡng trắng, ngăn ngừa lão hóa da.

- Bước 17: Chạy búa lạnh giúp se khít lỗ chân lông, khóa dưỡng chất lại trên da.

- Bước 18: Bôi kem dưỡng chống nắng.

- Bước 19: Hướng dẫn cách chăm sóc bảo vệ da.

+ Gói 4: Cấy tinh chất vàng 24k nhân sâm núi hoàng kim trẻ hóa, căng bóng làn da 15 năm tuổi (90 phút).

Nhân sâm núi Hàn Quốc được xem là loại nhân sâm tốt nhất trên thị trường Hàn Quốc. Thành phần saponin trong nhân sâm núi có tác dụng phục hồi da bị hư tổn, tái tạo tế bào da mới, dưỡng ẩm, làm mờ vết thâm, giảm nhăn, làm cho da săn chắc và duy trì sự trẻ hóa cho làn da. Đặc biệt, vì nhân sâm được chiết xuất từ thực vật tự nhiên nên rất an toàn khi sử dụng. Với liệu trình trẻ hóa da này, Văn phòng Chăm sóc Sắc đẹp OHUI sử dụng tinh chất nhân sâm núi hoàng kim - sản phẩm độc quyền OHUI để làm đẹp da cho bạn.

Liệu trình:

- Bước 1: Kiểm tra da phân tích tình trạng da.

- Bước 2: Ủ ánh sáng sinh học màu xanh lục giúp diệt khuẩn, làm kích nhân mụn ẩn dưới da trồi lên để dễ xử lý.

- Bước 3: Tẩy trang giúp loại bỏ lớp kem trang điểm, chống nắng, bụi bám trên bề mặt da.

- Bước 4: Rửa mặt bằng sữa rửa mặt đông y Hoàng Cung giúp loại bỏ sạch sâu bụi bẩn, bã nhờn trên da (sử dụng khăn giấy lụa làm sạch da mặt, mỗi khách một cặp, không dùng bọt biển, nên vệ sinh an toàn tuyệt đối).

- Bước 5: Xông nóng giải độc da bằng tinh dầu đặt trị mụn giúp giãn nở lỗ chân lông bít tắc, giúp nhẹ nhàng lấy nhân mụn mà không đau, không để lại sẹo.

- Bước 6: Hút mụn bằng ống thuỷ tinh chân không giúp hút sạch bã nhờn, bụi bẩn, vi khuẩn làm thông thoáng sâu trong lỗ chân lông (mỗi khách hàng một ống riêng biệt).

- Bước 7: Kiểm tra độ nhờn da qua ống thuỷ tinh chân không & ấn huyệt trên khuôn mặt giúp tuần hoàn máu, giúp cho quá trình trị liệu đạt hiệu quả cao.

- Bước 8: Vệ sinh da mặt lần nữa bằng nước cân bằng da.

- Bước 9: Kiểm tra và tiệt trùng dụng cụ cấy (mỗi khách một bộ).

- Bước 10: Cấy tinh chất sâm núi hoàng kim đưa dưỡng chất hấp thụ sâu vào trung bì của da, kích thích hình thành Collagen và Elastin giúp da săn chắc, sáng bóng, căng mịn đồng thời se khít lỗ chân lông nuôi dưỡng da, tăng đàn hồi cho da.

- Bước 11: Đắp mặt nạ lộc nhung nóng Đông y Hoàng Cung giúp kích thích lưu thông tuần hoàn mạch máu và mạch bạch huyết, giải độc tố da, tăng độ đàn hồi và săn chắc giúp trắng sáng và hồng hào.

- Bước 12: Chiếu ánh sáng sinh học Omega Light giúp giảm nếp nhăn, chống lão hóa da.

- Bước 13: Massage đầu, cổ, vai, gáy, làm lưu thông máu. Những động tác massage nhẹ nhàng sẽ giúp bạn có được khoảnh khắc thư giãn tuyệt vời.

- Bước 14: Rửa mặt sạch lớp mặt nạ.

- Bước 15: Chạy vitamin C bằng máy chạy serum C giúp da xóa đi những vết đốm màu làm tối và sạm da, làm sáng và ngăn chặn sự hình thành sắc tố melanin.

- Bước 16: Phun lạnh kết hợp nước cân bằng pH cho da,để se khít lỗ chân lông.

- Bước 17: Thoa kem dưỡng ẩm hoặc chống nắng giúp chăm sóc và bảo vệ da một cách tối ưu.

- Bước 18: Hướng dẫn cách chăm sóc da sau liệu trình để da hồi phục và cải thiện hiệu quả tối đa nhất.

Và kết thúc liệu trình với thời gian 90&rsquo;.

+ Gói 5: Trị thâm quầng mắt, chống nhăn, nâng mí mắt, tiêu bọng mắt bằng tinh chất dung dịch nuôi dưỡng tế bào mầm và chất dẫn xuất Hesperidin (90 phút).

Do nhiều nguyên nhân như làm việc quá sức, mất ngủ, do tuổi tác... khiến cho đôi mắt bạn bị thâm quầng, xuất hiện vết nhăn và tạo thành những bọng mỡ dưới mắt, làm cho đôi mắt kém tinh anh, sáng đẹp. Liệu trình chăm sóc vùng mắt bằng tinh chất dung dịch nuôi dưỡng tế bào mầm và chất dẫn xuất Hesperidin tại Văn phòng Chăm sóc Sức khỏe & Sắc đẹp OHUI giúp xóa tan quầng thâm, làm săn chắc vùng da quanh mắt, đồng thời đánh tan bọng mỡ mắt, cho đôi mắt thêm khỏe đẹp.

