INSERT INTO contents (content_id, program_id, title, body, content_type, status) VALUES (245, 173, 'Chính Sách & Điều Kiện Sử Dụng: Ruka Spa - Massage Body Đá Nóng + Foot + Xông Hơi + Đắp Mắt 75’', $BODY$Điều kiện sử dụng

