INSERT INTO contents (content_id, program_id, title, body, content_type, status) VALUES (247, 174, 'Chính Sách & Điều Kiện Sử Dụng: Ruka Spa - Trọn Gói Massage Body + Gội Đầu Dưỡng Sinh 135’', $BODY$Điều kiện sử dụng

- Thời hạn sử dụng voucher: từ 02/07/2026 đến 02/10/2026.

- Địa điểm sử dụng voucher: Ruka Spa - 153/3 Nguyễn Thị Minh Khai, Phường Phạm Ngũ Lão, Quận 1. ĐT: 0909 036268.

- Áp dụng cho 01 trong 02 gói dịch vụ (135 phút) tại Ruka Spa.

+ Gói 1:

1. Xông hơi không giới hạn thời gian.

2. Massage body Thụy Điển kết hợp bấm huyệt + tinh dầu + đá nóng + foot (60 phút).

3. Túi thảo dược đắp mắt thư giãn, giảm quầng thâm và vết nhăn.

4. Nằm gối nóng thảo dược giảm đau nhức, mệt mỏi.

5. Gội đầu dưỡng sinh + Massage đầu, cổ, vai, gáy + Đắp mặt nạ (60 phút).

+ Gói 2:

1. Xông hơi không giới hạn thời gian.

2. Massage body Thụy Điển kết hợp bấm huyệt + tinh dầu + đá nóng + foot (90 phút).

3. Túi thảo dược đắp mắt thư giãn, giảm quầng thâm và vết nhăn.

4. Nằm gối nóng thảo dược giảm đau nhức, mệt mỏi.

5. Gội đầu thư giãn (30 phút).

- Áp dụng vào tất cả các ngày trong tuần (kể cả Lễ). Giờ áp dụng: 9h-22h.

- Áp dụng cho cả nam và nữ.

- Một khách hàng được mua nhiều phiếu.

- Sử dụng 01 phiếu/ 01 người/ 01 gói dịch vụ (Không bù tiền).

- Không áp dụng đồng thời với các chương trình khuyến mãi khác.

- Khách hàng vui lòng đặt chỗ trước khi đến để được phục vụ tốt nhất.

- Phiếu không có giá trị quy đổi thành tiền mặt, không trả lại tiền thừa.

- Thanh toán online nhận ngay voucher điện tử.$BODY$, 'POLICY', 'ACTIVE');
INSERT INTO contents (content_id, program_id, title, body, content_type, status) VALUES (248, 174, 'Trải Nghiệm Dịch Vụ & Điểm Nổi Bật: Ruka Spa - Trọn Gói Massage Body + Gội Đầu Dưỡng Sinh 135’', $BODY$Thông tin chi tiết

Giữa nhịp sống hối hả của Sài Gòn, đôi khi món quà xa xỉ nhất lại chính là vài giờ đồng hồ được hoàn toàn im lặng và lắng nghe cơ thể mình. Hiểu được điều đó, Ruka Spa mang đến gói trị liệu đặc biệt kéo dài 135 phút, một hành trình chăm sóc chuyên sâu kết hợp giữa xông hơi giải độc, massage body Thụy Điển đi đá nóng và gội đầu dưỡng sinh. Đây không chỉ là một dịch vụ spa thông thường, mà là khoảng lặng tinh tế giúp bạn phục hồi sức khỏe, nuôi dưỡng làn da và tìm lại sự bình yên trong tâm hồn.

Bạn có thể lựa chọn 01 trong 02 gói dịch vụ, được thiết kế để chăm sóc cơ thể từ đầu đến chân.

Liệu trình mở đầu với xông hơi không giới hạn thời gian, giúp làm ấm cơ thể, kích thích tuần hoàn máu, hỗ trợ đào thải độc tố qua da và giúp các cơ bắp được thả lỏng trước khi bước vào các bước trị liệu chuyên sâu.

Điểm nhấn của cả hai gói là massage body Thụy Điển kết hợp bấm huyệt, tinh dầu, đá nóng và massage chân. Kỹ thuật massage nhẹ nhàng kết hợp các động tác nhấn huyệt giúp giải tỏa căng cơ, giảm đau mỏi vùng lưng, vai, cổ và chân. Hơi nóng từ đá nóng cùng tinh dầu thiên nhiên giúp các nhóm cơ được thư giãn sâu, tăng cường lưu thông máu, hỗ trợ giảm stress, cải thiện chất lượng giấc ngủ và mang lại cảm giác thư thái sau những ngày làm việc áp lực.

Liệu trình còn kết hợp túi thảo dược đắp mắt, giúp làm dịu đôi mắt mệt mỏi sau thời gian dài sử dụng máy tính, hỗ trợ giảm quầng thâm, giảm bọng mắt và mang lại cảm giác thư giãn dễ chịu. Bên cạnh đó, gối nóng thảo dược tác động bằng nhiệt ấm lên vùng cổ, vai và lưng, góp phần giảm đau nhức, làm dịu các cơ bị căng cứng và giúp cơ thể thả lỏng hoàn toàn.

Với Gói 1, bạn sẽ tiếp tục tận hưởng gội đầu dưỡng sinh kết hợp massage đầu, cổ, vai, gáy và đắp mặt nạ trong 60 phút. Những động tác massage nhẹ nhàng trên vùng đầu và vai gáy giúp kích thích tuần hoàn máu, giảm cảm giác nặng đầu, thư giãn hệ thần kinh, đồng thời làm sạch da đầu, chăm sóc mái tóc và bổ sung độ ẩm cho làn da với bước đắp mặt nạ.

Nếu lựa chọn Gói 2, bạn sẽ được trải nghiệm gội đầu thư giãn 30 phút, giúp làm sạch tóc và da đầu, kết hợp massage nhẹ nhàng để mang lại cảm giác sảng khoái, hoàn thiện hành trình chăm sóc cơ thể một cách trọn vẹn.

Liệu trình chi tiết:

+ Gói 1:

1. Xông hơi không giới hạn thời gian.

2. Massage body Thụy Điển kết hợp bấm huyệt + tinh dầu + đá nóng + foot (60 phút).

Bước 1: Khởi động ấn huyệt từ lòng bàn chân đến bả vai, giúp giảm căng thẳng vùng eo lưng, mang lại cảm giác dễ chịu.

Bước 2: Massage, ấn huyệt vùng lưng với tinh dầu thiên nhiên, giúp giảm căng cơ, giải tỏa stress.

Bước 3: Thoa tinh dầu thiên nhiên làm nóng và kích thích các huyệt đạo, miết xoa nhẹ nhàng, thấm sâu qua lớp tinh dầu nguyên chất vào bên trong các đường cơ lưng. Sau đó massage và bấm huyệt cổ vai gáy, tiếp đến massage và bấm huyệt lưng thật nhẹ nhàng.

Quý khách lại tận hưởng những kỹ năng miết xoa nhẹ nhàng vào bên trong các đường cơ lưng, nhào và bóp dẻo dai, nhuần nhuyễn một lần nữa. Cùng một lúc, mọi động tác chuyên nghiệp được thực hiện từ cổ xuống thắt lưng và từ thắt lưng trở lên.

Bước 4: Dùng đá nóng massage, ấn huyệt vùng lưng, giúp đẩy lùi mệt mỏi, bổ sung nguồn năng lượng mới cho cơ thể.

Bước 5: Massage, miết, nhào cơ nhẹ nhàng từ đùi non xuống gối, cẳng chân, mu bàn chân phía phải. Sau đó làm tương tự với phía bên trái. Bấm các huyệt từ hông xuống đùi, bắp chân và gan bàn chân, sau đó miết và xoa lại cho thấm huyệt.

Bước 6: Ủ đá nóng trên lưng.

Bước 7: Massage vùng đùi và bắp chân (trước và sau), giúp giảm đau nhức và tiêu mỡ, có kết hợp với đá nóng.

Bước 8: Massage và ấn huyệt bàn chân, lòng bàn chân giúp lưu thông khí huyết. Dùng đá nóng ấn vào các huyệt lòng bàn chân giúp đả thông kinh mạch.

Bước 9: Massage hai tay, thoa dầu và massage, miết, nhào cơ nhẹ nhàng hai cánh tay, bàn tay, ngón tay; bấm các huyệt cơ bản hai cánh tay và hai bàn tay. Sau đó dùng đá nóng massage 2 tay.

Bước 10: Massage và ấn huyệt đầu, vai, cổ. Dùng đá nóng massage vùng cổ vai gáy.

3. Túi thảo dược đắp mắt thư giãn, giảm quầng thâm và vết nhăn.

4. Nằm gối nóng thảo dược giảm đau nhức, mệt mỏi.

5. Gội đầu dưỡng sinh + Massage đầu, cổ, vai, gáy + Đắp mặt nạ (60 phút).

Bước 1: Khai thông massage ấn huyệt đầu.

Bước 2: Rửa mặt.

Bước 3: Đắp mặt nạ trắng da.

Bước 4: Gội đầu lần 1.

​

Bước 5: Massage cổ, vai, gáy.

Bước 6: Gội đầu lần 2.

Bước 7: Rửa mặt nạ, xả dưỡng tóc.

Bước 8: Massage đầu.

Bước 9: Sấy tóc.

Bước 10: Xịt dưỡng.

+ Gói 2:

1. Xông hơi không giới hạn thời gian.

2. Massage body Thụy Điển kết hợp bấm huyệt + tinh dầu + đá nóng + foot (90 phút).

